import Foundation

struct AdminConfiguration: Decodable {
    let projectName: String
    let adminURL: URL
    /// Admin route segment -> item reference prefix for each configured work
    /// kind (e.g. "features": "FR"), generated by `npm run sync:work-kinds`.
    let workItemRoutes: [String: String]?

    /// Older configs without `workItemRoutes` keep the built-in feature + bug routes.
    var resolvedWorkItemRoutes: [String: String] {
        workItemRoutes ?? ["features": "FR", "bugs": "BUG"]
    }

    static let current: AdminConfiguration = {
        guard
            let file = Bundle.main.url(forResource: "ProjectAdminConfig", withExtension: "json"),
            let data = try? Data(contentsOf: file),
            let config = try? JSONDecoder().decode(AdminConfiguration.self, from: data)
        else {
            preconditionFailure("ProjectAdminConfig.json is missing or invalid")
        }
        return config
    }()
}
